function validate([player1, player2]) {
  if (!Array.isArray(player1) || !Array.isArray(player2) || player1.length !== player2.length) return 'player1 and player2 need the same length.';
  if (player1.length < 1 || player1.length > 1000) return 'Each player bowls 1 to 1000 turns.';
  if ([...player1, ...player2].some(v => !Number.isInteger(v) || v < 0 || v > 10)) return 'Each turn knocks down 0 to 10 pins.';
  return null;
}

