function isWinner(player1, player2) {
  const score = (pins) => {
    let total = 0;
    for (let i = 0; i < pins.length; i++) {
      const strikeBefore = (i >= 1 && pins[i - 1] === 10) || (i >= 2 && pins[i - 2] === 10);
      if (strikeBefore) {
        total += 2 * pins[i];
      } else {
        total += pins[i];
      }
    }
    return total;
  };
  const first = score(player1);
  const second = score(player2);
  if (first > second) {
    return 1;
  }
  if (second > first) {
    return 2;
  }
  return 0;
}

