function isWinner(player1, player2) {
  // Count down the turns that are still doubled after each strike.
  const total = pins => {
    let sum = 0;
    let doubledLeft = 0;
    for (const x of pins) {
      sum += doubledLeft > 0 ? 2 * x : x;
      doubledLeft = Math.max(0, doubledLeft - 1);
      if (x === 10) doubledLeft = 2;
    }
    return sum;
  };
  const a = total(player1);
  const b = total(player2);
  return a === b ? 0 : a > b ? 1 : 2;
}

