function generate(rand, size) {
  const n = size === 'large' ? 800 + Math.floor(rand() * 201) : 1 + Math.floor(rand() * 7);
  const strikeChance = rand() * 0.6;
  const turn = () => (rand() < strikeChance ? 10 : Math.floor(rand() * 11));
  const player1 = Array.from({ length: n }, turn);
  const mode = rand();
  let player2;
  if (mode < 0.2) {
    // The same turns in reverse order: equal pins, but the doubling can differ.
    player2 = player1.slice().reverse();
  } else if (mode < 0.3) {
    player2 = player1.slice();
  } else {
    player2 = Array.from({ length: n }, turn);
  }
  return [player1, player2];
}
